func (s stockTransactionDo) ScanByPage(result interface{}, offset int, limit int) (count int64, err error) {
	count, err = s.Count()
	if err != nil {
		return
	}

	err = s.Offset(offset).Limit(limit).Scan(result)
	return
}

func (s stockTransactionDo) Scan(result interface{}) (err error) {
	return s.DO.Scan(result)
}

func (s stockTransactionDo) Delete(models ...*model.StockTransaction) (result gen.ResultInfo, err error) {
	return s.DO.Delete(models)
}

func (s *stockTransactionDo) withDO(do gen.Dao) *stockTransactionDo {
	s.DO = *do.(*gen.DO)
	return s
}
